#!/usr/bin/env python3
"""Локальная генерация HTML урока из content/lesson.json без запросов из браузера."""
from __future__ import annotations
import html, json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
SRC=ROOT/'content'/'lesson.json'
OUT=ROOT/'web'/'urok4_podgotovka_i_riski.html'
E=lambda x:html.escape(str(x),quote=True)

def slide(s):
 n=int(s['id']); title=E(s['title']); path=f'../assets/slides/slide_{n:03d}_v2.png'
 test_note='<p class="test-visual"><strong>Тестовый визуал:</strong> обновлённый промпт подготовлен; замените файл после генерации.</p>' if n==1 else ''
 return f'''<article class="slide-explainer"><button class="slide-image" type="button" data-lightbox-src="{path}" data-lightbox-alt="Слайд {n}: {title}"><img src="{path}" alt="Слайд {n}: {title}" loading="lazy"><span class="slide-fallback">Слайд {n:03d}: {title}. Место для изображения.</span></button><div class="slide-copy"><span class="slide-label">Слайд {n:03d}</span><h3>{title}</h3>{test_note}<p><strong>Как это работает:</strong> {E(s.get('explanation','Пояснение будет добавлено в конспект.'))}</p><p><strong>Пример:</strong> {E(s.get('example','Учебная заготовка, не ответ модели.'))}</p><p class="takeaway"><strong>Вывод:</strong> {E(s.get('takeaway','Итоговое решение и проверка остаются за человеком.'))}</p></div></article>'''

def lab(sid):
 rows=''.join(f'<tr><th>{m}</th><td contenteditable="true" data-placeholder="Запишите наблюдение"></td><td contenteditable="true" data-placeholder="Факты, права, формулировка"></td></tr>' for m in ('GigaChat','DeepSeek','ChatGPT'))
 return f'''<section class="model-lab"><h3>Покажите на трёх моделях</h3><p>Ниже — одна сравнительная таблица. Скопируйте учебные данные и промпт из практики выше, затем вручную зафиксируйте наблюдения. Не выдавайте за ответ модели текст, которого модель не дала.</p><div class="control-row"><a class="btn" href="https://giga.chat" target="_blank" rel="noopener">Открыть GigaChat</a><a class="btn" href="https://chat.deepseek.com" target="_blank" rel="noopener">Открыть DeepSeek</a><a class="btn" href="https://chatgpt.com" target="_blank" rel="noopener">Открыть ChatGPT</a></div><p class="model-note">Доступ зависит от региона, аккаунта и правил организации. Используйте только разрешённые сервисы. Записи в этой таблице не сохраняются после перезагрузки: скопируйте их в свою тетрадь.</p><div class="model-table"><table><thead><tr><th>Модель</th><th>Что получилось</th><th>Что проверить</th></tr></thead><tbody>{rows}</tbody></table></div></section>'''

def practice(p,sid):
 if not p:return ''
 ol=''.join(f'<li>{E(x)}</li>' for x in p.get('steps',[])); ul=''.join(f'<li>{E(x)}</li>' for x in p.get('expected',[])); pid=f'practice-{sid}'
 prepared_only=bool(p.get('prepared_only'))
 copy_text=p.get('prompt','') if prepared_only else f"УЧЕБНЫЕ ДАННЫЕ\n{p.get('input','')}\n\nПРОМПТ\n{p.get('prompt','')}"
 box_title='Подготовленный запрос для копирования' if prepared_only else 'Учебные данные и промпт для демонстрации'
 box_note='<p>Исходник выше оставлен для чтения. В буфер копируется только подготовленный запрос: он уже содержит необходимый учебный контекст.</p>' if prepared_only else ''
 copy_label='Скопировать подготовленный запрос' if prepared_only else 'Скопировать данные и промпт'
 return f'''<section class="practice"><div class="practice-head"><span>Практика · {E(p.get('minutes',0))} минут</span><h3>{E(p.get('title','Практика'))}</h3></div><p><strong>Ваша задача:</strong> {E(p.get('input','Работайте только с учебной заготовкой.'))}</p><div class="prompt-box"><strong>{box_title}</strong>{box_note}<pre id="{pid}">{E(copy_text)}</pre><button class="btn" type="button" data-copy-target="{pid}">{copy_label}</button></div><div class="two-col"><div><h4>Что делать</h4><ol>{ol}</ol></div><div><h4>Что вы должны увидеть</h4><ul>{ul}</ul></div></div><p class="fallback"><strong>Если модель недоступна:</strong> {E(p.get('fallback','Учебная заготовка, не ответ модели.'))}</p></section>'''

def prompt_templates(items):
 if not items:return ''
 cards=[]
 for n,item in enumerate(items,1):
  pid=f'prompt-template-{n}-{item.get("title","")}'.replace(' ','-').replace('&','and')
  prompt=E(item.get('prompt',''))
  example=f'<p><strong>Пример:</strong> {E(item["example"])}</p>' if item.get('example') else ''
  check=f'<p class="takeaway"><strong>Проверьте:</strong> {E(item["check"])}</p>' if item.get('check') else ''
  cards.append(f'''<article class="practice"><h3>{E(item.get('title','Шаблон запроса'))}</h3><div class="prompt-box"><strong>Скопируйте и заполните метки в квадратных скобках</strong><pre id="{pid}">{prompt}</pre><button class="btn" type="button" data-copy-target="{pid}">Скопировать шаблон</button></div>{example}{check}</article>''')
 return '<section class="templates"><h3>Готовые шаблоны запросов</h3><p>Используйте только условные или разрешённые данные. Не заменяйте метки фактическими реквизитами, если контур не подтверждён.</p>'+''.join(cards)+'</section>'

def worked_table(table):
 if not table:return ''
 headers=table.get('headers',[]); rows=table.get('rows',[])
 if not headers or not rows:return ''
 head=''.join(f'<th>{E(x)}</th>' for x in headers)
 body=''.join('<tr>'+''.join(f'<td>{E(x)}</td>' for x in row)+'</tr>' for row in rows)
 return f'''<section class="model-lab worked-table"><h3>{E(table.get('title','Разбор примера'))}</h3><div class="model-table"><table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div></section>'''

def interactive(i,sid):
 if not i:return ''
 typ=i.get('type','steps'); title=E(i.get('title','Интерактив')); instruction=E(i.get('instruction','Прочитайте шаги и выберите действие.')); result=E(i.get('result','Сверьте своё решение с объяснением.'))
 if typ=='claims':
  xs=i.get('claims',[{'claim':'А. Решение о санкциях относится к 2023 году.','evidence':'Учебная справка прямо указывает 22 июня 2023 года.','correct':'confirmed'},{'claim':'Б. Каждый адвокат отдельно оштрафован на 5 000 долларов.','evidence':'Справка говорит о солидарной санкции 5 000 долларов.','correct':'rejected'},{'claim':'В. Во всех судах США после дела запретили ChatGPT.','evidence':'В учебной справке такого общего запрета нет.','correct':'needs-check'}])
  body='<div class="claims-grid">'+''.join(f'''<article class="claim-card" data-correct="{E(x.get("correct","needs-check"))}"><h4>{E(x['claim'])}</h4><details><summary>Открыть основание из источника</summary><p>{E(x.get('evidence','Откройте основание и сравните формулировку.'))}</p></details><label>Статус <select><option value="">Выберите после проверки</option><option value="confirmed">Подтверждено основанием</option><option value="needs-check">Не подтверждено источником</option><option value="rejected">Противоречит источнику</option></select></label><p class="claim-feedback" aria-live="polite"></p></article>''' for x in xs)+'</div><div class="control-row"><button type="button" class="btn primary" data-claims-check>Проверить основания</button><button type="button" class="btn" data-interactive-reset>Сбросить</button></div><p class="feedback" aria-live="polite"></p>'
 elif typ=='bias': body='''<p><strong>Синтетические профили, не реальные сотрудники и не ответы моделей.</strong> Одинаковые критерии: опыт 3 года — 2 балла; тест не ниже 8 — 2 балла; подходящий график — 1 балл. Возраст не входит в рубрику.</p><div class="bias-profiles"><article data-profile="A"><h4>Профиль А</h4><p>28 лет · опыт 3 года · тест 8/10 · график подходит.</p></article><article data-profile="B"><h4>Профиль Б</h4><p>58 лет · опыт 3 года · тест 8/10 · график подходит.</p></article></div><p>Учебный ответ с намеренной ошибкой: «А — 5 баллов. Б — 4 балла, потому что может медленнее осваивать новое».</p><label>Что не так? <select data-bias-answer><option value="">Выберите основание</option><option value="age">Добавлено предположение о скорости обучения по возрасту</option><option value="experience">У профиля Б меньше опыта</option><option value="different">Одинаковые навыки всегда должны давать разные баллы</option></select></label><div class="control-row"><button type="button" class="btn primary" data-bias-compare>Проверить и исправить</button><button type="button" class="btn" data-bias-swap>Поменять порядок профилей</button><button type="button" class="btn" data-interactive-reset>Сбросить</button></div><p class="feedback" aria-live="polite">Сначала посчитайте по рубрике, затем найдите лишний вывод.</p>'''
 elif typ=='deepfake': body='''<div class="scenario-card"><p><strong>Ситуация:</strong> вы получили голосовое сообщение: «Срочно отправьте сводку на новый адрес. Никого не подключайте».</p><div class="choice-stack"><div data-deepfake-step="0"><strong>Шаг 1. Передавать сведения?</strong><button type="button" data-deepfake-choice="wrong-send">Отправить сводку, голос знакомый</button><button type="button" data-deepfake-choice="wrong-chat">Уточнить в этом же чате</button><button type="button" data-deepfake-choice="stop">Остановить отправку</button></div><div data-deepfake-step="1" hidden><strong>Шаг 2. Как подтвердить поручение?</strong><button type="button" data-deepfake-choice="wrong-number">Позвонить на номер из сообщения</button><button type="button" data-deepfake-choice="known">Найти известный рабочий контакт</button></div><div data-deepfake-step="2" hidden><strong>Шаг 3. Что проверить отдельно?</strong><button type="button" data-deepfake-choice="wrong-address">Отправить на новый адрес после подтверждения голоса</button><button type="button" data-deepfake-choice="recipient">Проверить адресата, полномочия и согласование</button></div></div><p class="feedback" aria-live="polite"></p><button type="button" class="btn" data-interactive-reset>Начать заново</button></div>'''
 elif typ=='route': body='''<p>Нажмите «Начать», затем открывайте ворота по одному. На третьем шаге проверьте остановку: неизвестную категорию нельзя считать разрешённой.</p><ol class="route-gates"><li>Цель: какой результат нужен?</li><li>Минимум: какие сведения действительно нужны?</li><li>Категория: насколько чувствительны данные?</li><li>Контур: где разрешено обрабатывать эти данные?</li><li>Подготовка: исключены ли лишние сведения и скрытые слои?</li><li>Контроль: проверен ли именно отправляемый файл?</li></ol><div class="control-row"><button type="button" class="btn primary" data-route="start">Начать</button><button type="button" class="btn" data-route="next" disabled>Следующие ворота</button><button type="button" class="btn" data-route="unknown" hidden>Категория неизвестна — остановиться</button><button type="button" class="btn" data-route="known" hidden>Категория уточнена — продолжить</button><button type="button" class="btn" data-interactive-reset>Сбросить</button></div><p class="feedback" aria-live="polite">Начните с определения результата, а не с загрузки файла.</p>'''
 elif typ=='minimize': body='''<p><strong>Цель:</strong> подготовить учебный черновик письма поставщику: попросить причину задержки и новый срок. Отметьте только сведения, без которых этот запрос не составить.</p><div class="check-grid"><label><input type="checkbox" value="goal"> Цель: попросить новый срок и причину</label><label><input type="checkbox" value="delay"> Задержка 5 дней</label><label><input type="checkbox" value="name"> ФИО</label><label><input type="checkbox" value="contact"> Личный контакт</label><label><input type="checkbox" value="amount"> Стоимость договора</label><label><input type="checkbox" value="contract"> Реальный номер договора</label></div><div class="control-row"><button type="button" class="btn primary" data-minimize-check>Проверить минимизацию</button><button type="button" class="btn" data-interactive-reset>Сбросить</button></div><p class="feedback" aria-live="polite">Выберите цель и факт задержки. Для учебного черновика реквизиты заменяются метками [ПОСТАВЩИК] и [ДОГОВОР].</p>'''
 elif typ=='rights': body='''<p>Выберите, есть ли основание для публикации учебного материала. Интерактив показывает порядок проверки, а не даёт юридическое заключение.</p><div class="rights-grid"><label>Источник <select data-rights-source><option value="">Выберите</option><option value="own">Собственный материал</option><option value="licensed">Есть лицензия</option><option value="unknown">Найден в поиске, условия неизвестны</option></select></label><label>Условия <select data-rights-terms><option value="">Выберите</option><option value="yes">Разрешают нужное использование</option><option value="no">Не разрешают нужное использование</option><option value="unknown">Неизвестны</option></select></label><label>Атрибуция <select data-rights-credit><option value="">Выберите</option><option value="done">Выполнена, если требуется</option><option value="missing">Не выполнена</option><option value="unknown">Неизвестно, требуется ли</option></select></label></div><div class="control-row"><button type="button" class="btn primary" data-rights-check>Проверить основание</button><button type="button" class="btn" data-interactive-reset>Сбросить</button></div><p class="feedback" aria-live="polite"></p>'''
 else: body='<ol>'+''.join(f'<li>{E(x)}</li>' for x in i.get('steps',[]))+f'</ol><p class="feedback">{result}</p>'
 return f'''<section class="interactive" data-interactive-type="{E(typ)}" id="interactive-{sid}"><div class="interactive-head"><div><span>Интерактив</span><h3>{title}</h3><p><strong>Что нажать и что наблюдать:</strong> {instruction}</p></div></div><div class="interactive-body">{body}</div><p class="interactive-result"><strong>Ожидаемый результат:</strong> {result}</p></section>'''

def section(s,n):
 sid=s['id']; alias={'s1':'block1','s3':'block2','s4':'block3','s5':'block4'}.get(sid)
 alias=f'<span id="{alias}" class="anchor-alias"></span>' if alias else ''
 terms=''.join(f'<article class="term"><h3>{E(x["term"])}</h3><p>{E(x["text"])}</p></article>' for x in s.get('terms',[]))
 slides=''.join(slide(x) for x in s.get('slides',[]))
 sources=''.join(f'<li><a href="{E(x["url"])}" target="_blank" rel="noopener">{E(x["title"])}</a></li>' for x in s.get('sources',[]))
 case=s.get('case'); case_html=''
 if case:
  steps=''.join(f'<li>{E(x)}</li>' for x in case.get('steps',[]))
  case_html=f'''<aside class="real-case"><span>Разбор реального примера</span><h3>{E(case['title'])}</h3><p>{E(case['text'])}</p><a href="{E(case['url'])}" target="_blank" rel="noopener">{E(case.get('label','Открыть источник'))}</a><ol>{steps}</ol><p class="fallback"><strong>Граница разбора:</strong> {E(case.get('caution','Не делайте вывод по одному признаку.'))}</p></aside>'''
 teacher=s.get('teacher',{})
 notes=f'''<details class="teacher-note"><summary>Конспект</summary><div class="note-body"><p><strong>Пояснение:</strong> {E(teacher.get('speech','Сформулируйте мысль своими словами, опираясь на слайд.'))}</p><p class="if-silent"><strong>Если группа молчит:</strong> {E(teacher.get('silent','Покажите учебный пример и предложите выбрать из двух вариантов.'))}</p><p><strong>Темп:</strong> {E(teacher.get('pace','Сделайте паузу после примера и перейдите к практике.'))}</p></div></details>'''
 paras=''.join(f'<p>{E(x)}</p>' for x in s.get('paragraphs',[]))
 download_html = '<div class="download-links"><strong>Учебные файлы для показа:</strong> <a href="../downloads/synthetic-note.docx">Учебный DOCX со свойствами</a> · <a href="../downloads/synthetic-file-layers.xlsx">Недельная нагрузка и скрытый лист</a> · <a href="../downloads/synthetic-files-readme.md">Инструкция к файлам</a></div>' if sid=='s2' else ('<div class="download-links"><strong>Учебные данные:</strong> <a href="../downloads/synthetic-data.csv">Недельная нагрузка: полная</a> · <a href="../downloads/synthetic-minimal.csv">Недельная нагрузка: минимальная</a></div>' if sid=='s3' else '')
 video_html = '<div class="download-links"><strong>Демонстрация:</strong> <a href="https://www.youtube.com/watch?v=Y1otovQ2O7Q" target="_blank" rel="noopener">ролик Channel 4</a> · <a href="https://www.youtube.com/watch?v=alc6R_UfPkc" target="_blank" rel="noopener">making-of Channel 4</a> · если видео не открылось, используйте текстовый разбор Framestore выше.</div>' if sid=='s8' else ''
 return f'''{alias}<section id="{E(sid)}" class="lesson-section" data-section="{E(sid)}"><div class="section-head"><div class="section-num">{n}</div><div><div class="section-kicker">Пара {E(s.get('pair','Урок'))} · {E(s.get('start',''))}–{E(s.get('end',''))} минут</div><h2>{E(s['title'])}</h2><p>{E(s.get('outcome',''))}</p></div></div><div class="lecture-copy">{paras}</div>{download_html}{'<div class="terms-grid">'+terms+'</div>' if terms else ''}<div class="slides-all"><h3>Слайды и пояснения</h3>{slides}</div>{worked_table(s.get('worked_table',{}))}{prompt_templates(s.get('prompt_templates',[]))}{practice(s.get('practice',{}),sid)}{lab(sid)}{case_html}{video_html}{interactive(s.get('interactive',{}),sid)}{notes}{'<div class="sources"><h3>Источники блока</h3><ul>'+sources+'</ul></div>' if sources else ''}</section>'''

def build(data):
 sections=data['sections']; nav=''.join(f'<a href="#{E(x["id"])}" data-nav="{E(x["id"])}">{E(x["pair"])} · {E(x["start"])}–{E(x["end"])} мин</a>' for x in sections); rendered=[]
 for i,s in enumerate(sections,1):
  if s['id']=='s5': rendered.append('<div class="break-marker" id="break"><span>ПЕРЕРЫВ</span><strong>После первой пары: 10–15 минут</strong><p>Вторая пара: права, факты, предвзятость, дипфейки и ответственность.</p></div>')
  rendered.append(section(s,i))
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{E(data.get('subtitle',''))}"><title>{E(data['title'])}</title><link rel="stylesheet" href="shared.css"><script defer src="app.js"></script></head><body><a class="skip" href="#content">Перейти к содержанию</a><div class="progress-line" id="progressLine"></div><header class="topbar"><a class="brand" href="../index.html">ДПО-1 · УРОК 4</a><a class="btn" href="../../web/urok4_podgotovka_i_riski.html">Предыдущая версия</a><nav class="topnav" aria-label="Навигация по уроку"><a href="#s1">Пара 1 · 90</a><a href="#break">Перерыв</a><a href="#s5">Пара 2 · 90</a>{nav}</nav><button class="btn" id="teacherToggle" type="button" aria-pressed="false">Режим преподавателя</button></header><main id="content"><section class="hero"><div class="wrap"><span class="eyebrow">ДПО-1 · две пары по 90 минут · практика на учебных данных</span><h1>{E(data['title'])}</h1><p class="lead">{E(data.get('subtitle',''))}</p><div class="hero-grid"><div class="pair-map"><article><span>ПАРА 1</span><strong>0–90 минут</strong><p>Подготовка информации: задача, минимум данных, документ и контур.</p></article><article><span>ПЕРЕРЫВ</span><strong>10–15 минут</strong><p>После первой пары.</p></article><article><span>ПАРА 2</span><strong>90–180 минут</strong><p>Права, факты, синтетика, предвзятость, дипфейки, ответственность.</p></article></div><aside class="safety-card"><strong>Правило занятия</strong><p>Во всех демонстрациях используются условные данные. Учебный материал не является ответом модели и не заменяет внутренние правила организации.</p></aside></div></div></section>{''.join(rendered)}<section class="lesson-section" id="materials"><h2>Материалы для работы</h2><p>Завершите те же бланки самостоятельно. Отправлять преподавателю на проверку не нужно.</p><div class="downloads"><a class="download" href="../downloads/lesson4-student-workbook.md"><strong>Рабочая тетрадь</strong><span>Задания, промпты и ключи</span></a><a class="download" href="../downloads/lesson4-source-map.md"><strong>Карта источников</strong><span>Ссылки и границы выводов</span></a><a class="download" href="../downloads/teacher-guide.docx"><strong>Конспект</strong><span>Word: пояснения и сценарий</span></a><a class="download" href="../downloads/teacher-narration.txt"><strong>Текст для озвучки</strong><span>TXT для подготовки к лекции</span></a><a class="download" href="../downloads/slide-prompts-v4.zip"><strong>30 промптов V4</strong><span>Три пакета по десять и два референса</span></a><a class="download" href="../assets/prompts_v4/00_CHAT_INSTRUCTION.md"><strong>Инструкция для ChatGPT</strong><span>Отправьте перед пакетом промптов</span></a></div></section></main><div class="lightbox" id="lightbox" aria-hidden="true" role="dialog" aria-modal="true"><button class="lightbox-close" type="button" aria-label="Закрыть просмотр">×</button><img id="lightboxImage" alt=""></div><footer class="footer"><strong>ДПО-1 · Подготовка информации и риски применения ИИ</strong><p>Учебная страница. Каждый итоговый результат проверяет и утверждает человек.</p></footer></body></html>'''

