 if not SRC.exists(): raise SystemExit(f'Нет исходника: {SRC}')
 data=json.loads(SRC.read_text(encoding='utf-8-sig'))
 if {'title','subtitle','sections'}-data.keys(): raise SystemExit('lesson.json не соответствует контракту')
 if len(data['sections'])!=9: raise SystemExit('Ожидается ровно 9 секций')
